2	import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { attachmentServiceClient } from "@/connect";
4	import {
5	  type Attachment,
6	  BatchDeleteAttachmentsRequestSchema,
7	  type ListAttachmentsRequest,
8	  ListAttachmentsRequestSchema,
9	} from "@/types/proto/api/v1/attachment_service_pb";
10	
11	// Query keys factory
12	export const attachmentKeys = {
13	  all: ["attachments"] as const,
14	  lists: () => [...attachmentKeys.all, "list"] as const,
15	  list: (filters?: Partial<ListAttachmentsRequest>) => [...attachmentKeys.lists(), filters] as const,
16	  details: () => [...attachmentKeys.all, "detail"] as const,
17	  detail: (name: string) => [...attachmentKeys.details(), name] as const,
18	};
19	
20	// Hook to fetch attachments
21	export function useAttachments() {
22	  return useQuery({
23	    queryKey: attachmentKeys.lists(),
24	    queryFn: async () => {
25	      const { attachments } = await attachmentServiceClient.listAttachments(create(ListAttachmentsRequestSchema, {}));
26	      return attachments;
27	    },
28	  });
29	}
30	
31	export function useInfiniteAttachments(request: Partial<ListAttachmentsRequest> = {}, options?: { enabled?: boolean }) {
32	  return useInfiniteQuery({
33	    queryKey: attachmentKeys.list(request),
34	    queryFn: async ({ pageParam }) => {
35	      const response = await attachmentServiceClient.listAttachments(
36	        create(ListAttachmentsRequestSchema, {
37	          ...request,
38	          pageToken: pageParam || "",
39	        } as Record<string, unknown>),
40	      );
41	      return response;
42	    },
43	    initialPageParam: "",
44	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
45	    staleTime: 1000 * 60,
46	    gcTime: 1000 * 60 * 5,
47	    enabled: options?.enabled ?? true,
48	  });
49	}
50	
51	// Hook to create/upload attachment
52	export function useCreateAttachment() {
53	  const queryClient = useQueryClient();
54	
55	  return useMutation({
56	    mutationFn: async (attachment: Attachment) => {
57	      const result = await attachmentServiceClient.createAttachment({ attachment });
58	      return result;
59	    },
60	    onSuccess: () => {
61	      // Invalidate attachments list
62	      queryClient.invalidateQueries({ queryKey: attachmentKeys.lists() });
63	    },
64	  });
65	}
66	
67	// Hook to delete attachment
68	export function useDeleteAttachment() {
69	  const queryClient = useQueryClient();
70	
71	  return useMutation({
72	    mutationFn: async (name: string) => {
73	      await attachmentServiceClient.deleteAttachment({ name });
74	      return name;
75	    },
76	    onSuccess: (name) => {
77	      // Remove from cache
78	      queryClient.removeQueries({ queryKey: attachmentKeys.detail(name) });
79	      // Invalidate lists
80	      queryClient.invalidateQueries({ queryKey: attachmentKeys.lists() });
81	    },
82	  });
83	}
84	
85	export function useBatchDeleteAttachments() {
86	  const queryClient = useQueryClient();
87	
88	  return useMutation({
89	    mutationFn: async (names: string[]) => {
90	      await attachmentServiceClient.batchDeleteAttachments(create(BatchDeleteAttachmentsRequestSchema, { names }));
91	      return names;
92	    },
93	    onSuccess: (names) => {
94	      for (const name of names) {
95	        queryClient.removeQueries({ queryKey: attachmentKeys.detail(name) });
96	      }
97	      queryClient.invalidateQueries({ queryKey: attachmentKeys.lists() });
98	    },
99	  });
